toolArgs.file_text:
@page "/settings"
@rendermode InteractiveServer
@using sv_ff8f702751bd483298f82fb88ea9af63.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <!-- Left sidebar navigation -->
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="nav flex-column">
            @foreach (var section in _sections)
            {
                <li class="nav-item">
                    <button class="nav-link @(section == _activeSection ? "active" : "")"
                            @onclick="() => SetActiveSection(section)">
                        <span class="nav-icon">@GetSectionIcon(section)</span>
                        @section
                    </button>
                </li>
            }
        </ul>
    </nav>

    <!-- Main content area -->
    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            <!-- Toast notification -->
            @if (_showToast)
            {
                <div class="settings-toast @(_toastIsError ? "toast-error" : "toast-success")">
                    @_toastMessage
                </div>
            }

            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </div>
</div>

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;

    // Toast
    private bool _showToast;
    private string _toastMessage = "";
    private bool _toastIsError;

    // Profile
    private UserProfile? _savedProfile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    // Notifications
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = ["#general", "#random", "#off-topic", "#engineering", "#design", "#announcements"];
    private HashSet<string> _mutedChannels = [];

    // Security
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private string? _sessionToRevoke;
    private bool _showRevokeConfirm;

    // Appearance
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private readonly string[] _themes = ["Light", "Dark", "System"];
    private readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData("Profile");
        _loading = false;
    }

    private async Task SetActiveSection(string section)
    {
        _activeSection = section;
        _showToast = false;
        await LoadSectionData(section);
    }

    private async Task LoadSectionData(string section)
    {
        switch (section)
        {
            case "Profile":
                _savedProfile = await SettingsService.GetProfileAsync();
                ResetProfileFields();
                break;
            case "Notifications":
                var prefs = await SettingsService.GetNotificationPrefsAsync();
                _emailNotifications = prefs.EmailNotifications;
                _pushNotifications = prefs.PushNotifications;
                _weeklyDigest = prefs.WeeklyDigest;
                _mutedChannels = [.. prefs.MutedChannels];
                break;
            case "Security":
                _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                _twoFactorEnabled = _securitySettings.TwoFactorEnabled;
                _changePasswordExpanded = false;
                _currentPassword = _newPassword = _confirmPassword = "";
                break;
            case "Appearance":
                var appearance = await SettingsService.GetAppearanceAsync();
                _theme = appearance.Theme;
                _fontSize = appearance.FontSize;
                _language = appearance.Language;
                _compactMode = appearance.CompactMode;
                break;
        }
    }

    private void ResetProfileFields()
    {
        if (_savedProfile is null) return;
        _displayName = _savedProfile.DisplayName;
        _email = _savedProfile.Email;
        _avatarUrl = _savedProfile.AvatarUrl;
        _bio = _savedProfile.Bio;
    }

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
        _showToast = true;
        StateHasChanged();
        await Task.Delay(3000);
        _showToast = false;
        StateHasChanged();
    }

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    // ── Profile ──

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges() => ResetProfileFields();

    private RenderFragment RenderProfileSection() => __builder =>
    {
        <h3 class="section-title">Profile</h3>

        <div class="card settings-card">
            <div class="card-body">
                <!-- Avatar preview -->
                <div class="avatar-section mb-4">
                    <div class="avatar-preview">
                        @if (!string.IsNullOrWhiteSpace(_avatarUrl))
                        {
                            <img src="@_avatarUrl" alt="Avatar" class="avatar-img" />
                        }
                        else
                        {
                            <div class="avatar-placeholder">👤</div>
                        }
                    </div>
                    <div class="avatar-url-display">
                        <label class="form-label text-muted small">Avatar URL</label>
                        <input type="url" class="form-control form-control-sm" @bind="_avatarUrl" placeholder="https://example.com/avatar.png" />
                    </div>
                </div>

                <div class="mb-3">
                    <label class="form-label">Display Name</label>
                    <input type="text" class="form-control" @bind="_displayName" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="_email" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Bio</label>
                    <textarea class="form-control" rows="4" @bind="_bio"></textarea>
                </div>

                <div class="d-flex gap-2">
                    <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </div>
        </div>
    };

    // ── Notifications ──

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, [.. _mutedChannels]);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h3 class="section-title">Notifications</h3>

        <div class="card settings-card">
            <div class="card-body">
                <div class="mb-4">
                    <h6 class="mb-3">Notification Channels</h6>

                    <div class="form-check form-switch mb-2">
                        <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                        <label class="form-check-label" for="emailNotif">Email Notifications</label>
                    </div>

                    <div class="form-check form-switch mb-2">
                        <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                        <label class="form-check-label" for="pushNotif">Push Notifications</label>
                    </div>

                    <div class="form-check form-switch mb-2">
                        <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                        <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
                    </div>
                </div>

                <div class="mb-4">
                    <h6 class="mb-3">Muted Channels</h6>
                    @foreach (var channel in _allChannels)
                    {
                        var isMuted = _mutedChannels.Contains(channel);
                        var channelId = $"mute-{channel.Replace("#", "")}";
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="checkbox" id="@channelId"
                                   checked="@isMuted"
                                   @onchange="e => ToggleMutedChannel(channel, (bool)e.Value!)" />
                            <label class="form-check-label" for="@channelId">@channel</label>
                        </div>
                    }
                </div>

                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </div>
    };

    // ── Security ──

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", true);
            return;
        }
        if (_newPassword.Length < 8)
        {
            await ShowToast("Password must be at least 8 characters.", true);
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = _newPassword = _confirmPassword = "";
        _changePasswordExpanded = false;
        await ShowToast("Password updated successfully!");
    }

    private void ShowRevokeConfirmation(string sessionId)
    {
        _sessionToRevoke = sessionId;
        _showRevokeConfirm = true;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        _showRevokeConfirm = false;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
        await ShowToast("Session revoked.");
    }

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h3 class="section-title">Security</h3>

        <!-- Change Password -->
        <div class="card settings-card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center"
                 style="cursor: pointer;" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                <h6 class="mb-0">Change Password</h6>
                <span>@(_changePasswordExpanded ? "▲" : "▼")</span>
            </div>
            @if (_changePasswordExpanded)
            {
                <div class="card-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>

                    @if (_securitySettings?.LastPasswordChange is not null)
                    {
                        <p class="text-muted small mt-2 mb-0">
                            Last changed: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                        </p>
                    }
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="card settings-card mb-3">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch mb-0">
                    <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
                </div>
            </div>
        </div>

        <!-- Active Sessions -->
        <div class="card settings-card">
            <div class="card-header">
                <h6 class="mb-0">Active Sessions</h6>
            </div>
            <div class="card-body p-0">
                <div class="table-responsive">
                    <table class="table table-hover mb-0">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @if (_securitySettings?.Sessions is not null)
                            {
                                @foreach (var (session, index) in _securitySettings.Sessions.Select((s, i) => (s, i)))
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@FormatLastActive(session.LastActive)</td>
                                        <td>
                                            @if (index == 0)
                                            {
                                                <span class="badge bg-info">Current</span>
                                            }
                                            else
                                            {
                                                <button class="btn btn-outline-danger btn-sm"
                                                        @onclick="() => ShowRevokeConfirmation(session.Id)">
                                                    Revoke
                                                </button>
                                            }
                                        </td>
                                    </tr>
                                }
                            }
                        </tbody>
                    </table>
                </div>
            </div>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (_showRevokeConfirm)
        {
            <div class="modal-backdrop show"></div>
            <div class="modal d-block" tabindex="-1">
                <div class="modal-dialog modal-dialog-centered">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">Revoke Session</h5>
                            <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                        </div>
                        <div class="modal-body">
                            <p>Are you sure you want to revoke this session? The user will be signed out on that device.</p>
                        </div>
                        <div class="modal-footer">
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            <button class="btn btn-danger" @onclick="ConfirmRevokeSession">Revoke Session</button>
                        </div>
                    </div>
                </div>
            </div>
        }
    };

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    // ── Appearance ──

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }

    private string PreviewFontSize => _fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private string PreviewBackground => _theme switch
    {
        "Dark" => "#1e1e2e",
        "System" => "#f0f0f5",
        _ => "#ffffff"
    };

    private string PreviewTextColor => _theme == "Dark" ? "#e0e0e0" : "#212529";

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <h3 class="section-title">Appearance</h3>

        <div class="card settings-card mb-3">
            <div class="card-body">
                <!-- Theme -->
                <div class="mb-4">
                    <h6 class="mb-2">Theme</h6>
                    @foreach (var theme in _themes)
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                   value="@theme" checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>

                <!-- Font Size -->
                <div class="mb-4">
                    <h6 class="mb-2">Font Size</h6>
                    @foreach (var size in _fontSizes)
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                                   value="@size" checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <h6 class="mb-2">Language</h6>
                    <select class="form-select" style="max-width: 250px;"
                            @bind="_language">
                        @foreach (var lang in _languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="card settings-card">
            <div class="card-header">
                <h6 class="mb-0">Preview</h6>
            </div>
            <div class="card-body p-0">
                <div class="live-preview"
                     style="background: @PreviewBackground; color: @PreviewTextColor; font-size: @PreviewFontSize; padding: @(_compactMode ? "0.75rem" : "1.5rem"); transition: all 0.3s ease; border-radius: 0 0 0.375rem 0.375rem;">
                    <h5 style="color: @PreviewTextColor; margin-bottom: @(_compactMode ? "0.25rem" : "0.75rem");">
                        Dashboard Preview
                    </h5>
                    <p style="margin-bottom: @(_compactMode ? "0.25rem" : "0.5rem");">
                        This is a preview of how your content will look with the selected appearance settings.
                    </p>
                    <div class="d-flex gap-2 flex-wrap" style="margin-bottom: @(_compactMode ? "0.25rem" : "0.5rem");">
                        <span class="badge bg-primary">Label</span>
                        <span class="badge bg-success">Active</span>
                        <span class="badge bg-warning text-dark">Pending</span>
                    </div>
                    <p class="mb-0 text-muted small">
                        Theme: @_theme · Font: @_fontSize · Language: @_language · Compact: @(_compactMode ? "On" : "Off")
                    </p>
                </div>
            </div>
        </div>
    };
}

